review=T(['موضوع','پاسخ کوتاه برای بازیابی','منبع'],[
 ['میکروبیوتا','محل و تعادل تعیین‌کننده‌اند؛ حضور طبیعی برابر بیماری نیست.',refs([3,4,6])],
 ['رقابت','جای اتصال، غذا، فرآوردهٔ مهاری؛ همراهی با ایمنی.',refs([4,5,6])],
 ['پلاک','اتصال، ماتریکس، همکاری و دیررس‌ها؛ قند و اسید برای پوسیدگی.',refs([7,8])],
 ['روده','تراکم از ابتدای روده به انتها بیشتر؛ نوع تولد و تغذیه ترکیب را تغییر می‌دهند.',refs([9,10])],
 ['محل‌های شاخص','پوست اپیدرمیدیس؛ بینی اورئوس؛ دهان ویریدانس؛ پلاک موتانس؛ کولون فراژیلیس و اشریشیا کلی.',refs([11])],
 ['مکمل‌ها','پروبیوتیک میکروب؛ پری‌بیوتیک غذای حمایتی؛ سین‌بیوتیک ترکیب.',refs([12,13])],
 ['فراژیلیس','گرم منفی، بی‌هوازی، کپسول، بتالاکتاماز؛ تحمل اکسیژن با SOD.',refs([13,15])],
 ['عفونت مختلط','مصرف اکسیژن توسط هوازی‌ها، فرصت بی‌هوازی‌ها، آسیب و نکروز بیشتر.',refs([17,18,19])],
 ['نمونه','نمایندهٔ محل واقعی؛ آلودگی سطح و مواجهه با اکسیژن دو مشکل جدا.',refs([20])],
 ['پرفرینجنس','بزرگ، مستطیلی، غیرمتحرک؛ انتشار سریع برابر حرکت نیست.',refs([23])],
 ['سم‌های اصلی','آلفا لسیتیناز؛ بتا نکروز؛ اپسیلون نفوذپذیری؛ یوتا دو قسمتی.',refs([23,24])],
 ['نوع‌ها','A: α؛ B: αβɛ؛ C: αβ؛ D: αɛ؛ E: αι؛ چارچوب خود جزوه.',refs([24])],
 ['ناگلر','آلفا و لسیتیناز در مقایسه با مهار پادسم؛ ظاهر متن نیازمند بررسی.',refs([24,26])],
 ['کزاز','کاهش گابا و گلیسین؛ کاهش مهار؛ انقباض و اسپاسم.',refs([29,30])],
 ['ایمنی','فعال با پاسخ میزبان؛ غیرفعال با پادتن آماده؛ سم آزاد از متصل جدا.',refs([29,30,31])],
 ['بوتولیسم','مهار استیل‌کولینِ عصب–عضله؛ کاهش تحریک؛ فلج شل.',refs([32])],
 ['سه شکل بوتولیسم','غذایی سم بیرون؛ نوزادی سم در روده؛ زخم سم در محل زخم.',refs([32,34])],
 ['دیفیسیل','کاهش رقبا، سم A و B، اختلال اسکلت و اتصال، آسیب سد و اسهال.',refs([34,35])]])

def build(name='استاد حاکمی',slug='hakemi',ordinal='دوم',sessions='سوم، یازدهم و دوازدهم'):
    count=len(b.lessons); recall=sum(len(l['questions']) for l in b.lessons)
    css=b.CSS
    font=base64.b64encode((ROOT/'_work/vazirmatn.woff2').read_bytes()).decode()
    css='@font-face{font-family:Vazirmatn;src:url(data:font/woff2;base64,'+font+') format("woff2");font-weight:100 900;font-display:swap;}\n'+css
    css=css.replace("font-family:Tahoma,'Segoe UI',Arial,sans-serif","font-family:Vazirmatn,Tahoma,Arial,sans-serif").replace("font-family:'Segoe UI',Arial,sans-serif","font-family:Vazirmatn,Arial,sans-serif")
    b.JS=b.JS.replace('bacteriology-haji-khani-v1','bacteriology-hakemi-v1')
    header=f'<header class="hero"><div class="hero-top"><div class="eyebrow">باکتری‌شناسی · راهنمای جزوه</div><a class="source-link" href="../{SOURCE}" target="_blank" rel="noopener">مشاهدهٔ جزوهٔ اصلی</a></div><div class="hero-grid"><div class="hero-copy"><h1><strong>{name}</strong></h1><p class="sub">{b.GUIDE_TOPICS[name]}</p><div class="hero-stats"><span><strong>{count}</strong>درس</span><span><strong>4</strong>بخش</span><span><strong>35</strong>صفحه</span></div></div><nav class="hero-route" aria-label="چهار بخش راهنما"><p>مسیر این فایل</p><ol>'+''.join(f'<li><a href="#part-{i}"><span>{i}</span>{title}</a></li>' for i,(title,sub) in PARTS.items())+'</ol></nav></div><div class="hero-bottom"><p class="source">تمرین تشریحی · جلسه‌های سوم، یازدهم و دوازدهم</p></div></header>'
    toc=[];content=[]
    for part,(title,sub) in PARTS.items():
        toc.append(f'<li><a class="part-link" href="#part-{part}">بخش {part} · {title}</a></li>')
        content.append(f'<div class="part-heading" id="part-{part}"><p class="overline">بخش {part} از 4</p><h2>{title}</h2><p>{sub}</p></div>')
        for i,l in enumerate(b.lessons,1):
            if l['part']!=part: continue
            lid=f'lesson-{i:02}'
            toc.append(f'<li><a href="#{lid}">{i:02} · {l["title"]}</a></li>')
            content.append(f'<article class="lesson" id="{lid}"><div class="lesson-top"><span class="lesson-num">{i:02}</span><h3>{l["title"]}</h3></div>{refs(l["pages"])}<p class="overview">{l["overview"]}</p><details class="lesson-body" {"open" if i==1 else ""}><summary>خواندن درس</summary><div class="goals"><strong>بعد از این درس بتوانم:</strong>{U(l["goals"])}</div>{l["body"]}<div class="memory"><strong>کمک حافظه</strong><p>{l["memory"]}</p><span class="caption">راهنمای حافظهٔ ساخته‌شده برای مطالعه</span></div><div class="checklist"><details class="lesson-checklist"><summary>فهرست مرور درس</summary>{U(l["check"])}</details><label><input type="checkbox" data-lesson-check="{lid}" aria-label="درس {i} مرور شد">این درس را مرور کردم</label></div></details></article>')
    nav='<ol>'+''.join(toc)+'</ol>'
    intro=f'<section class="intro"><h2>هر بار یک درس</h2><p class="method">هدف‌ها را ببین، درس را بخوان، سپس به زبانهٔ پرسش‌ها برو و بدون نگاه پاسخ بنویس. پاسخ پیشنهادی و نکات ضروری را برای خودارزیابی استفاده کن.</p><p class="section-lead">مرور همان روز، روز بعد و چند روز بعد پیشنهاد مطالعه است؛ برنامه با زمان خودت تنظیم می‌شود. هیچ تمرین ساخته‌شده‌ای پیش‌بینی امتحان نیست.</p><p class="mini-source">ارجاع‌ها شمارهٔ صفحهٔ فایل اصلی از 1 تا 35 هستند؛ شماره‌های چاپی هر جلسه دوباره شروع می‌شوند. پژوهش بیرونی انجام نشده است. ابهام‌های منبع در زبانهٔ اصلاحات آمده‌اند؛ متن درسی دربارهٔ بیماری و درمان برای مطالعه است. جزئیات اجرایی آزمایش‌ها به اصل مفهومی آن‌ها خلاصه شده‌اند.</p><div class="toolbar"></div><div class="progress-box"><div class="progress-line"><strong>پیشرفت مطالعه</strong><span id="progress-label" aria-live="polite">0 از {count} درس مرور شده</span></div><progress id="progress" max="{count}" value="0"></progress><p class="storage" id="storage-message">پیشرفت در همین مرورگر ذخیره می‌شود.</p></div><noscript><p>درس‌ها و پاسخ‌های بازشدنی بدون جاوااسکریپت قابل مطالعه‌اند؛ ذخیرهٔ پیشرفت و کنترل‌های گروهی به آن نیاز دارند.</p></noscript></section>'
    flag_index=''.join(f'<details><summary>{n}. {title}</summary><p>{text}</p>{refs(pages)}<a href="#flag-{n}">دیدن در متن درس</a></details>' for n,title,text,pages in b.flags)
    cov=T(['صفحات فایل','محتوا','درس'],[[refs(p),text,'، '.join(f'<a href="#lesson-{i:02}">{i}</a>' for i in ids) if ids else 'اداری'] for p,text,ids in coverage])
    def section(id,title,lead,body):return f'<section class="reference-section" id="{id}"><h2>{title}</h2><p class="section-lead">{lead}</p>{body}<a class="back" href="#top">بازگشت به آغاز</a></section>'
    extra=section('quick-review','مرور سریع','پس از مطالعه، ستون پاسخ را بپوشان و هر مسیر را با جملهٔ کامل توضیح بده. موارد علامت‌دار پاسخ قطعی ندارند.',review)
    extra+=section('written-practice','تمرین نوشتاری ترکیبی','این 8 پرسش برای مطالعه ساخته شده‌اند؛ پرسش واقعی یا پیش‌بینی امتحان نیستند. ابتدا بدون پاسخ بنویس. نکات ضروری ابزار خودارزیابی‌اند، نه بارم رسمی.',P('قالب پاسخ: تعریف، ویژگی مرتبط، مراحل علت و معلول، پیامد و مثال. در مقایسه، برای هر دو طرف یک محور مشترک انتخاب کن.')+''.join(mixed))
    extra+=section('source-questions','پرسش‌های خود جزوه','پرسش‌های داخل متن با نگارش خواناتر از تمرین‌های تازه جدا شده‌اند. پاسخ‌های تدوین‌شده بر همان صفحات تکیه دارند؛ توصیهٔ مبهم نیز علامت دارد. منبع مجموعهٔ تست چندگزینه‌ای ندارد.',''.join(source_questions))
    extra+=section('uncertainties','اصلاحات و ابهام‌های منبع',f'{len(b.flags)} موردِ گروه‌بندی‌شده؛ ادعاهای مشکوک بی‌صدا اصلاح نشده‌اند. هر مورد، صفحه و راه برگشت به درس دارد.', '<div class="flag-list">'+flag_index+'</div>')
    extra+=section('coverage','پوشش صفحات منبع','همهٔ صفحات، جدول‌ها و شکل‌های آموزشی بررسی شده‌اند. تصویرها به توضیح یا جدول تبدیل شده‌اند؛ برای ظاهر اصلی، صفحهٔ منبع را باز کن. جزئیات اجرایی آزمایش‌ها به مفهوم امتحانی خلاصه شده‌اند.',cov+P(f'{count} درس، {recall} پرسش بازیابی و فلش‌کارت، {len(mixed)} تمرین ترکیبی و {len(source_questions)} پرسش منبع. درس‌ها از پرسش‌ها جدا هستند.'))
    html=f'<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>استاد حاکمی · راهنمای مطالعهٔ باکتری‌شناسی</title><style>{css}</style></head><body><a class="screen-reader" href="#lessons">رفتن به درس‌ها</a><div class="site" id="top">{header}<details class="mobile-contents"><summary>فهرست درس‌ها و بخش‌ها</summary>{nav}</details><div class="layout"><nav class="sidebar" aria-label="فهرست درس‌ها"><h2>مسیر مطالعه</h2>{nav}</nav><main class="main">{intro}<div id="lessons">'+''.join(content)+'</div>'+extra+'<footer class="footnote">راهنمای فایل دوم · جزوهٔ استاد حاکمی · مستقل و بدون نیاز به اینترنت. برای ارجاع‌ها، فایل اصلی را در پوشهٔ بالاتر نگه دار. ذخیرهٔ پیشرفت به مرورگر و محل بازشدن فایل وابسته است.</footer></main></div></div></body></html>'
    html=b.tabbed_page(html).replace('۴۳ پرسش',f'{recall} پرسش').replace('۴۳ کارت',f'{recall} کارت').replace('۱ از ۴۳',f'1 از {recall}').replace('كل الدروس','همهٔ درس‌ها')
    for superscript,number in [('³','3'),('⁵','5'),('⁶','6'),('⁸','8'),('¹⁰','10'),('¹¹','11')]:
        html=html.replace(superscript,'<sup>'+number+'</sup>')
    license=(ROOT/'_work/font-license.txt').read_text(encoding='utf-8').replace('--','- -')
    html=html.replace('</head>','<!-- Embedded Vazirmatn font license:\n'+license+'\n--></head>')
    total_pages=max(p for pages,_,_ in coverage for p in pages)
    html=html.replace('استاد حاکمی',name).replace('فایل دوم','فایل '+ordinal).replace('جلسه‌های سوم، یازدهم و دوازدهم',sessions).replace('bacteriology-hakemi-v1','bacteriology-'+slug+'-v1')
    html=html.replace('<strong>35</strong>صفحه',f'<strong>{total_pages}</strong>صفحه').replace('از 1 تا 35','از 1 تا '+str(total_pages))
    html=html.replace('<strong>4</strong>بخش',f'<strong>{len(PARTS)}</strong>بخش').replace(' از 4</p>',f' از {len(PARTS)}</p>')
    html=html.replace('این 8 پرسش',f'این {len(mixed)} پرسش')
    if not source_questions:
        html=html.replace('پرسش‌های داخل متن با نگارش خواناتر از تمرین‌های تازه جدا شده‌اند. پاسخ‌های تدوین‌شده بر همان صفحات تکیه دارند؛ توصیهٔ مبهم نیز علامت دارد. منبع مجموعهٔ تست چندگزینه‌ای ندارد.','در این فایل، پرسش مستقل و صریحی برای بازنویسی شناسایی نشد. پرسش‌های این راهنما همگی تمرین ساخته‌شده‌اند؛ تأکیدهای استاد در درس‌ها حفظ شده‌اند.')
    html=b.persian_numbers(html)
    target=ROOT/(name+'.html');target.write_text(html,encoding='utf-8')
    manifest={'source':name+'.pdf','source_pages':total_pages,'lessons':count,'recall_questions':recall,'mixed_questions':len(mixed),'source_questions':len(source_questions),'flags':len(b.flags),'page_coverage':[{'pages':p,'sections':text,'lessons':ids} for p,text,ids in coverage]}
    (ROOT/('_work/'+slug+'/coverage.json')).write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps({'output':str(target),'bytes':target.stat().st_size,**{k:v for k,v in manifest.items() if k!='page_coverage'}},ensure_ascii=True))

if __name__=='__main__':build()
